      document.getElementById('soap-o').value = '';
      document.getElementById('soap-a').value = '';
      document.getElementById('soap-p').value = '';
      document.getElementById('visit-date').valueAsDate = new Date();
    }

    function renderNotes() {
      const historyEl = document.getElementById('history-list');
      historyEl.innerHTML = '';

      const patient = patients.find(p => p.id === activePatientId);

      if (patient.notes.length === 0) {
        historyEl.innerHTML = '<p style="color: #a0aec0; font-size: 0.9rem;">No visits logged yet.</p>';
        return;
      }

      patient.notes.forEach(note => {
        const card = document.createElement('div');
        card.className = 'card';
        card.innerHTML = `
          <div class="card-header">
            <span>Date: ${note.date}</span>
            <span style="color: #e53e3e; cursor: pointer;" onclick="deleteNote('${note.id}')">Delete</span>
          </div>
          ${note.s ? `<div class="soap-section"><strong>S:</strong> ${escapeHtml(note.s)}</div>` : ''}
          ${note.o ? `<div class="soap-section"><strong>O:</strong> ${escapeHtml(note.o)}</div>` : ''}
          ${note.a ? `<div class="soap-section"><strong>A:</strong> ${escapeHtml(note.a)}</div>` : ''}
          ${note.p ? `<div class="soap-section"><strong>P:</strong> ${escapeHtml(note.p)}</div>` : ''}
        `;
        historyEl.appendChild(card);
      });
    }

    function deleteNote(noteId) {
      if (!confirm("Are you sure you want to remove this visit note?")) return;
      const patient = patients.find(p => p.id === activePatientId);
      patient.notes = patient.notes.filter(n => n.id !== noteId);
      persistData();
      renderNotes();
    }

    function deleteActivePatient() {
      if (!confirm("Are you sure you want to permanently delete this patient and their notes?")) return;
      patients = patients.filter(p => p.id !== activePatientId);
      persistData();
      activePatientId = null;
      document.getElementById('active-workspace').style.display = 'none';
      document.getElementById('no-selection').style.display = 'flex';
      renderPatientList();
    }

    function escapeHtml(text) {
      return text.replace(/[\"&<>]/g, function (a) {
        return { '"': '&quot;', '&': '&amp;', '<': '&lt;', '>': '&gt;' }[a];
      }).replace(/\n/g, '<br>');
    }

    // Initial Load
    renderPatientList();
  </script>
</body>
</html>
